using DitaStudio.Core.Model;
using DitaStudio.Core.Project;
using DitaStudio.Core.Validation;
using Xunit;

public class NoTodoRuleTests
{
    [Fact]
    public void FindsTodoInText()
    {
        var doc = DitaDocument.Parse("<topic id=\"t\"><title>Тема</title><body><p>TODO: дописать</p></body></topic>");
        var issue = Assert.Single(new NoTodoRule().Check(doc));
        Assert.Equal(IssueSeverity.Error, issue.Severity);
        Assert.Equal("p", issue.Node?.Name);
    }

    [Fact]
    public void WholeProject()
    {
        var project = new DitaProject(@"..\..\..\TestProject");
        project.Scan();
        var issues = project.ValidateAll(new IValidationRulePlugin[] { new NoTodoRule() });
        Assert.DoesNotContain(issues, i => i.Message.Contains("TODO"));
    }
}
